recs=[]
recs.append(R(6511203,"کیلیفورنیا کھجور اور کاجو کا چکن اسٹر فرائی","یہ آسان چکن اسٹر فرائی کیلیفورنیا کی کھجوروں کی مٹھاس اور لال مرچ کے فلیکس کی ہلکی سی تیزی کے ساتھ خوب جچتا ہے۔ زیادہ مسالے دار ڈش کے لیے ایک تازہ ہری مرچ کاٹ کر ہری پیاز کے ساتھ ڈالیں۔ اسے کسی سالم اناج کے ساتھ ملائیں تو آپ کے پاس دبلے پروٹین، فائبر اور پیچیدہ کاربوہائیڈریٹس سے بھرپور مکمل کھانا ہوگا جو یقیناً سب کو پسند آئے گا۔","4","1 کپ",
["1 1/2 کھانے کے چمچ سبزیوں کا تیل","2 کھانے کے چمچ ادرک (باریک کٹا ہوا)","4 جوے لہسن (باریک کٹے ہوئے)","3 ڈنڈی ہری پیاز (سفید اور ہلکے ہرے حصے کٹے ہوئے)","1/4 - 1/2 چائے کا چمچ لال مرچ کے فلیکس","12 اونس بغیر ہڈی اور بغیر کھال کے چکن بریسٹ (1 انچ کے ٹکڑوں میں کٹے ہوئے)","1 درمیانی شملہ مرچ (لمبی پتلی قتلوں میں)","1 چھوٹی بروکلی (کاٹنے کے سائز کے ٹکڑوں میں کٹی ہوئی (~2 کپ))","1/3 کپ رائس سرکہ","2 کھانے کے چمچ کم سوڈیم والی سویا ساس","6 عدد کیلیفورنیا کھجوریں (گٹھلی نکلی ہوئی اور باریک کٹی ہوئی)","2-4 کھانے کے چمچ پانی (اختیاری)","1 کپ ہرا دھنیا (کٹا ہوا)","1 کپ تلسی (باریک کٹی ہوئی یا کٹی ہوئی)","2 کھانے کے چمچ تازہ لائم کا رس (1 درمیانے لائم سے)","1/3 کپ کاجو (بھنے ہوئے)"],
["ایک کڑاہی یا اونچے کناروں والے سوتے پین میں درمیانی تیز آنچ پر تیل، ادرک، لہسن اور ہری پیاز ڈالیں اور تقریباً 2 منٹ پکائیں۔","لال مرچ کے فلیکس اور چکن ڈالیں اور کبھی کبھار ہلاتے ہوئے تقریباً 4 منٹ پکائیں۔ چکن کو پین سے نکال کر ایک طرف رکھ دیں۔","پین میں شملہ مرچ اور بروکلی ڈالیں اور کبھی کبھار ہلاتے ہوئے 2–3 منٹ پکائیں۔","چکن کو واپس پین میں ڈالیں اور رائس سرکہ، سویا ساس اور کھجوریں بھی ڈالیں۔ پورے پین میں اچھی طرح ملائیں۔ آنچ کو درمیانی ہلکی کر دیں، مائع کو ہلکے ابال پر لائیں اور اسے گاڑھا یا شیرے جیسا ہونے تک پکنے دیں۔ اگر پتلی ساس درکار ہو تو 2–4 کھانے کے چمچ پانی ڈالیں۔ تقریباً 5 منٹ ہلکی آنچ پر رہنے دیں۔","پین کو آنچ سے ہٹا لیں۔ ہرا دھنیا، تلسی اور لائم کا رس ملا دیں۔ بھنے ہوئے کاجو سے سجائیں۔","اختیاری: براؤن چاول یا کسی اور اناج کے ساتھ پیش کریں۔","نوٹ: آپ شملہ مرچ اور/یا بروکلی کی جگہ دوسری سبزیاں استعمال کر سکتے ہیں۔"]))
recs.append(R(6511716,"زکینی اور تازہ مکئی کا سکوٹاش","اس ترکیب کے لیے تازہ بھٹے کو ابلتے پانی میں 8 منٹ پکا لیں۔ بھٹوں کو ٹھنڈا ہونے دیں، پھر تیز چاقو سے دانے بھٹے سے الگ کر لیں۔","6","1/2 کپ",
["1 کھانے کا چمچ زیتون کا تیل","1 درمیانی پیاز (چکور کٹی ہوئی)","2 جوے لہسن (باریک کٹے ہوئے)","1 درمیانی زکینی (چکور کٹی ہوئی)","4 درمیانے مکئی کے بھٹے (تازہ، پکے ہوئے اور دانے بھٹے سے الگ کیے ہوئے)","1 (14.5 اونس) ڈبہ کالی پھلیاں (پانی نکالی ہوئی اور دھوئی ہوئی)","2 کھانے کے چمچ تازہ پارسلے (کٹا ہوا)","1/2 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ"],
["ایک بڑے فرائنگ پین میں درمیانی تیز آنچ پر زیتون کا تیل ڈالیں۔ پیاز ڈالیں اور 5-6 منٹ سوتے کریں یا جب تک پیاز شفاف ہونا شروع نہ ہو جائے۔","لہسن اور زکینی ڈالیں اور مزید 4-5 منٹ سوتے کریں جب تک زکینی بس نرم ہونا شروع نہ ہو جائے۔","مکئی ڈالیں اور 2-3 منٹ سوتے کریں۔ پھر باقی اجزاء ڈالیں اور گرم ہونے تک پکائیں۔"]))
