recs.append(R(6513384,"مولی اور تربوز ارگولا سلاد","اس ذیابیطس کے لیے موزوں مولی اور تربوز ارگولا سلاد سے اپنے مہمانوں کو متاثر کریں۔ گرمیوں کا یہ بہترین سلاد میٹھے تربوز کو تیکھی مولیوں، کرکری پیاز اور کھٹی ڈریسنگ کے ساتھ پیش کرتا ہے۔","6","2 کپ ارگولا، 1 کپ تربوز اور مولی کا مرکب",
["2 کھانے کے چمچ ریڈ وائن سرکہ","1/4 چائے کا چمچ کوشر نمک","1/8 چائے کا چمچ کالی مرچ","1/4 کپ زیتون کا تیل","2 کھانے کے چمچ تازہ پودینہ (پتے ہاتھ سے توڑے ہوئے)","1 چھوٹا بغیر بیج کا تربوز (چکور کٹا ہوا، تقریباً 3 ½–4 کپ)","1/2 چھوٹی وڈالیا پیاز (چکور کٹی ہوئی)","1 گڈی مولی (ڈنٹھل کاٹ کر باریک قتلوں میں کٹی ہوئی)","2 اونس کم چکنائی والا فیٹا پنیر","5 اونس بیبی ارگولا"],
["ایک چھوٹے پیالے میں سرکہ، نمک، کالی مرچ، زیتون کا تیل اور پودینہ پھینٹ کر ملا لیں۔","ایک بڑے پیالے میں تربوز، پیاز، مولی اور فیٹا پنیر ملائیں۔","ڈریسنگ ڈالیں اور آہستگی سے ہلا کر ملا دیں۔ بیبی ارگولا کے بستر پر پیش کریں۔"]))
recs.append(R(6514260,"رس بھری، 1 کپ","رس بھری کی غذائی معلومات","1","1 کپ",["1 کپ رس بھری"],[]))
recs.append(R(6514294,"لہسن ادرک والا بینگن","ایشیائی انداز کی یہ سبزی کی ڈش بینگن، مشروم اور پھوٹے ہوئے مونگ کو لہسن ادرک ہوئسن ساس میں پیش کرتی ہے۔ ترکیب میں چینی یا جاپانی بینگن استعمال ہوتا ہے جو لمبا اور پتلا ہوتا ہے۔ اگر آپ کو چینی بینگن نہ ملے تو عام بینگن استعمال کر کے اسے 1 انچ کے ٹکڑوں میں کاٹ لیں۔ یہ سائیڈ ڈش یا سبزی خور مین ڈش ہو سکتی ہے۔ مکمل سبزی خور کھانے کے لیے ٹوفو یا پودوں سے حاصل ہونے والا کوئی اور پروٹین کا ذریعہ شامل کریں۔\n\nPowered by Homemade، پیشکش Davita۔","4","3/4 کپ",
["2 کھانے کے چمچ تل کا تیل","2 عدد جاپانی بینگن (1 انچ کے ٹکڑوں میں کٹے ہوئے)","2 چائے کے چمچ باریک کٹا ہوا تازہ ادرک","2 جوے لہسن (باریک کٹے ہوئے)","1/2 کپ کٹے ہوئے مشروم","1 کپ تازہ پھوٹے ہوئے مونگ","1/4 کپ تازہ تلسی (کٹی ہوئی)","1/4 چائے کا چمچ کٹی ہوئی لال مرچ کے فلیکس","1 کھانے کا چمچ ہوئسن ساس"],
["ایک بڑے فرائنگ پین میں تل کا تیل گرم کریں۔ بینگن، ادرک، لہسن، مشروم اور پھوٹے ہوئے مونگ ڈالیں۔ درمیانی تیز آنچ پر بینگن کے نرم ہونا شروع ہونے تک اسٹر فرائی کریں، 4-6 منٹ۔","بینگن میں تلسی، مرچ کے فلیکس اور ہوئسن ساس ڈالیں۔ 1-2 منٹ مزید پکاتے رہیں۔ آنچ سے ہٹائیں اور پیش کریں۔"]))
recs.append(R(6515306,"پھول گوبھی کے اسٹیکس چمچوری کے ساتھ","چمچوری کے ساتھ پھول گوبھی کے اسٹیکس ایک لذیذ اور پیٹ بھرنے والی سبزی خور ڈش ہے جو پھول گوبھی کو دل بھرنے والے اسٹیکس میں بدل دیتی ہے اور انہیں تازہ، چٹپٹی چمچوری ساس کے ساتھ پیش کرتی ہے۔","8","1 پھول گوبھی کا اسٹیک + 2 کھانے کے چمچ چمچوری",
["2 عدد پھول گوبھی (بڑی)","1 کھانے کا چمچ زیتون کا تیل","3/4 چائے کا چمچ کوشر نمک (تقسیم شدہ)","1/2 چائے کا چمچ کالی مرچ (تقسیم شدہ)","1/2 کپ تازہ پارسلے (باریک کٹا ہوا)","2 کھانے کے چمچ تازہ ہرا دھنیا (باریک کٹا ہوا)","2 جوے لہسن (باریک کٹے ہوئے)","1/2 چائے کا چمچ خشک اوریگانو","1/4 چائے کا چمچ پسی ہوئی لال مرچ کے فلیکس (ذائقے کے مطابق کم یا زیادہ کریں)","2 کھانے کے چمچ ریڈ وائن سرکہ","1/4 کپ ایکسٹرا ورجن زیتون کا تیل"],
["اوون کو 425 ڈگری F پر پہلے سے گرم کریں۔","پھول گوبھی کے باہری پتے ہٹا دیں۔ ڈنٹھل کے سرے کو کاٹ کر چپٹی بنیاد بنا لیں۔","ہر پھول گوبھی کو 1 انچ موٹے قتلوں میں کاٹ لیں تاکہ پھول گوبھی کے اسٹیکس بن جائیں۔","پھول گوبھی کے اسٹیکس کو بیکنگ شیٹ پر رکھیں۔ دونوں طرف 1 کھانے کا چمچ زیتون کا تیل لگائیں اور کوشر نمک اور کالی مرچ چھڑکیں۔","پھول گوبھی کے اسٹیکس کو سنہری بھورا اور نرم ہونے تک روسٹ کریں، تقریباً 20 منٹ۔","جب پھول گوبھی روسٹ ہو رہی ہو، چمچوری ساس تیار کریں۔ ایک پیالے میں باریک کٹا پارسلے، ہرا دھنیا، باریک کٹا لہسن، خشک اوریگانو، لال مرچ کے فلیکس، ریڈ وائن سرکہ، ایکسٹرا ورجن زیتون کا تیل، کوشر نمک اور کالی مرچ ملائیں۔ اچھی طرح ملنے تک پھینٹیں۔","جب پھول گوبھی کے اسٹیکس تیار ہو جائیں تو انہیں سرونگ پلیٹوں میں منتقل کریں۔","ہر پھول گوبھی کے اسٹیک پر چمچوری ساس فراخ دلی سے چمچ سے ڈالیں۔"]))
recs.append(R(6516194,"بھنے ہوئے چقندر، سیب اور کیسو فریسکو کا سلاد","ایک مزیدار سلاد جس میں آپ چقندر جیسی خزاں کی پیداوار شامل کر سکتے ہیں۔","4","1 کپ",
["1 چائے کا چمچ کینولا تیل","3 چھوٹے چقندر (کل تقریباً 12 اونس)","1 کھانے کا چمچ تازہ لائم کا رس","2 چائے کے چمچ ایوکاڈو کا تیل","1/4 چائے کا چمچ کوشر نمک","1/4 چائے کا چمچ کالی مرچ (کوٹی ہوئی)","2 کپ گولڈن ڈیلیشس سیب (چھلے ہوئے اور چکور ٹکڑوں میں کٹے ہوئے (1/2 انچ کے ٹکڑے))","1 کھانے کا چمچ ہرا دھنیا (باریک کٹا ہوا)","1 کھانے کا چمچ کیسو فریسکو (چورا کیا ہوا)","1/4 کپ پیلی پیاز (قتلوں میں کٹی ہوئی)"],
["اوون کو 400°F پر پہلے سے گرم کریں۔","چقندر پر کینولا تیل مل دیں اور یقینی بنائیں کہ پوری سطح پر لگ جائے۔ چقندروں میں چند سوراخ کر دیں تاکہ حرارت گزر سکے اور پکنے کا عمل تیز ہو۔ چقندروں کو ایک چھوٹی بیکنگ ڈش میں رکھیں اور فوائل سے مضبوطی سے ڈھانپ دیں۔ چقندروں کو 1 گھنٹہ 10 منٹ روسٹ کریں، جب تک کانٹے سے چقندر کا گودا آسانی سے چھید نہ سکے۔ اوون سے نکالیں اور چقندروں کو براہ راست برف کے پانی والے پیالے میں ڈال دیں۔ اس سے چقندر تیزی سے ٹھنڈے ہو جائیں گے، پکنے کا عمل رک جائے گا اور چھلکے اتارنا بہت آسان ہو جائے گا۔ جب چقندر ٹھنڈے ہو جائیں تو کاغذی تولیے سے چھلکے اتار دیں۔ چقندروں کو 1/2 انچ کے چکور ٹکڑوں میں کاٹ کر ایک طرف رکھ دیں۔","ایک پیالے میں ایوکاڈو کا تیل، لائم کا رس، نمک اور کالی مرچ ڈالیں اور 30 سیکنڈ تک تیزی سے پھینٹیں تاکہ آپ کی ڈریسنگ تیار ہو جائے۔ ایک طرف رکھ دیں۔","الگ پیالے میں سیب، 2 کپ چقندر کے ٹکڑے، ہرا دھنیا، کیسو فریسکو اور پیاز ڈالیں اور آہستگی سے ملا لیں۔ ڈریسنگ ڈالیں اور ایک بار پھر ملا لیں۔ اب یہ پیش کرنے کے لیے تیار ہے۔ نوش فرمائیں!"]))
recs.append(R(6517612,"اطالوی پھلیوں اور ہری پتیوں کا سلاد","پھلیاں اور ہری پتیاں ایک کلاسک اطالوی کھانا یا سائیڈ ڈش ہے۔ ذیابیطس کے لیے موزوں اس ورژن میں محفوظ کیے ہوئے ہیم کی جگہ ٹرکی بیکن اور چکن ساسیج استعمال کیا گیا ہے۔ انہیں بیبی گرینز اور کینیلینی بینز کے ساتھ ملا کر سلاد بنایا جاتا ہے۔ یہ بحیرہ روم کے ایک کلاسک کھانے کا دل بھرنے والا، تازہ انداز ہے۔","4","1 کپ سلاد کی ہری پتیاں + 1 اونس چکن ساسیج",
["2 سلائس ٹرکی بیکن (½ انچ کے ٹکڑوں میں کٹے ہوئے)","2 عدد اطالوی مسالے والے چکن ساسیج (½ انچ کے گول ٹکڑوں میں کٹے ہوئے)","4 کپ پاور گرینز","1/2 کپ کم سوڈیم والی کینیلینی بینز (دھوئی ہوئی اور پانی نکالی ہوئی)","1/4 کپ لال پیاز (قتلے)","2 کھانے کے چمچ ایکسٹرا ورجن زیتون کا تیل","1 کھانے کا چمچ سفید بالسامک سرکہ","2 جوے لہسن (باریک کٹے ہوئے)","1/4 چائے کا چمچ کالی مرچ","1/8 چائے کا چمچ کوشر نمک","2 کھانے کے چمچ پارمیزان پنیر (باریک قتلے کیا ہوا)"],
["ایک بڑے فرائنگ پین میں ٹرکی بیکن کو کرکرا ہونے تک اور ساسیج کو بھورا ہونے تک پکائیں۔","ہری پتیاں، کینیلینی بینز اور پیاز ایک بڑے پیالے میں رکھیں۔","ایک چھوٹے پیالے میں زیتون کا تیل، سرکہ، لہسن اور کالی مرچ پھینٹ کر ملا لیں۔ سلاد پر ڈالیں اور ہری پتیوں پر لگانے کے لیے ملا دیں۔ اوپر پارمیزان پنیر چھڑکیں۔"]))
recs.append(R(6518949,"ٹماٹر اور زکینی کی سالسا","یہ ٹماٹر اور زکینی کی سالسا ایک ہمہ جہت اور غذائیت بخش انتخاب ہے جو تازہ، موسمی پیداوار کے ذائقوں کا جشن مناتی ہے۔ اس کی کرکری ساخت اور شوخ ذائقے کو اپنے کھانوں میں ایک دلکش اضافے کے طور پر یا الگ ناشتے کے طور پر نوش کریں۔","4","1/2 کپ",
["2 بڑے روما (پلم) ٹماٹر (چکور کٹے ہوئے)","1 چھوٹی زکینی (باریک چکور کٹی ہوئی)","1/4 کپ لال پیاز (باریک کٹی ہوئی)","1/4 کپ تازہ ہرا دھنیا (کٹا ہوا)","1 چھوٹی ہالاپینو مرچ (بیج نکلی ہوئی اور باریک کٹی ہوئی)","2 جوے لہسن (باریک کٹے ہوئے)","2 کھانے کے چمچ تازہ لائم کا رس","1/4 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ"],
["ایک مکسنگ پیالے میں چکور کٹے ٹماٹر، چکور کٹی زکینی، باریک کٹی لال پیاز، کٹا ہرا دھنیا اور باریک کٹی ہالاپینو مرچ ملائیں۔ مرکب میں باریک کٹا لہسن ڈالیں۔ اجزاء پر تازہ لائم کا رس ڈالیں۔ سالسا میں نمک اور کالی مرچ ڈالیں۔","تمام اجزاء کو آہستگی سے اس وقت تک ملائیں جب تک وہ اچھی طرح مل نہ جائیں اور لائم کے رس اور مسالوں سے لگ نہ جائیں۔","سالسا کو تقریباً 10–15 منٹ رکھا رہنے دیں تاکہ ذائقے آپس میں مل جائیں۔ اپنی پسند کے مطابق مسالا ایڈجسٹ کریں"]))
recs.append(R(6519498,"شہد، ونیلا اور رس بھری کے دہی کے پاپسیکلز","شہد، ونیلا اور رس بھری کے یہ دہی کے پاپسیکلز ٹھنڈک پانے کا ایک کریمی طریقہ ہیں۔ ذیابیطس کے لیے موزوں، یہ بچوں کا پسندیدہ میٹھا ہے جو گرمیوں کے لیے بہترین ہے۔","4","1 پاپسیکل",
["1 کپ سادہ بغیر چکنائی والا یونانی دہی","1 کپ منجمد رس بھری","1 کھانے کا چمچ شہد","1 چائے کا چمچ ونیلا ایکسٹریکٹ"],
["بلینڈر میں دہی اور رس بھری کی پیوری بنا لیں۔","بلینڈ ہو جانے کے بعد شہد اور ونیلا مرکب میں ڈالیں۔ اچھی طرح بلینڈ کریں۔","مرکب کو پاپسیکل مولڈز میں ڈال دیں۔ 8 گھنٹے یا رات بھر جمنے دیں۔"]))
recs.append(R(6520204,"لیموں والا پیسٹو حمس","اس حمس کو بغیر نشاستے والی سبزیوں، سالم گندم کے پیٹا، یا سالم اناج کے کریکرز کے ساتھ ڈپ کے طور پر ناشتے میں نوش کریں۔","5","1/4 کپ",
["1 (14.5 اونس) ڈبہ چنے (کابلی چنے) (پانی نکالے ہوئے اور دھوئے ہوئے)","2 کھانے کے چمچ بوتل بند پیسٹو ساس","2 کھانے کے چمچ لیموں کا رس (1 درمیانے لیموں سے)","1/2 چائے کا چمچ تازہ پسی ہوئی کالی مرچ"],
["تمام اجزاء فوڈ پروسیسر یا بلینڈر میں ڈالیں اور ہموار ہونے تک بلینڈ کریں۔"]))
recs.append(R(6520840,"پالک، ایوکاڈو اور گرمیوں کی بیریوں کا سلاد","یہ سپر فوڈ سلاد اینٹی آکسیڈنٹس اور شوخ، گرمیوں کے ذائقوں سے بھرپور ہے۔ اسے گرِل کیے ہوئے چکن کی ڈش، جیسے Grilled Lime Chicken Fajitas، یا مچھلی، جیسے Grilled Salmon with Mango and Tomato Salsa، کے ساتھ پیش کریں۔ سلاد ڈریسنگ بنانے کا آسان طریقہ چاہیے؟ ڈریسنگ کے تمام اجزاء ڈھکن والے جار میں ڈالیں۔ ڈھکن مضبوطی سے بند کریں اور اچھی طرح ہلائیں جب تک سب کچھ مل نہ جائے۔ اگر آپ یہ سلاد پہلے سے تیار کر رہے ہیں تو ڈریسنگ پیش کرنے سے ذرا پہلے ڈالیں۔","8","1 کپ",
["10 اونس تازہ بیبی پالک","1 کپ چکور یا قتلوں میں کٹی اسٹرابیریاں","1/2 کپ بلیو بیریز","1 درمیانا ایوکاڈو (چکور کٹا ہوا)","1/3 کپ باریک چکور یا قتلوں میں کٹی لال پیاز","2 کھانے کے چمچ زیتون کا تیل","2 کھانے کے چمچ سفید بالسامک یا شیمپین سرکہ","1 چائے کا چمچ شہد","1 کھانے کا چمچ لائم (رس نکالا ہوا)","1 جوا لہسن (باریک کٹا ہوا)","1/4 چائے کا چمچ کالی مرچ"],
["پالک، اسٹرابیریاں، بلیو بیریز، ایوکاڈو اور پیاز ایک بڑے سلاد باؤل میں رکھیں۔","ایک چھوٹے پیالے میں زیتون کا تیل، سرکہ، شہد، لائم کا رس، لہسن اور کالی مرچ پھینٹ کر ملا لیں۔","ڈریسنگ سلاد پر ڈالیں اور برابر لگنے تک ملا دیں۔"]))
